// 54/54. Every instruction matches retail. Six bytes differ because retail
// loads the refreshed pointer into eax and derives the mask in ecx, while
// this build loads it into ecx and derives the mask in eax.
// Pin needed: ?bfmeReleaseERB@BfmeTexERB@@QAEXXZ,0x009EB7A0 (Release_Ref)

class BfmeTexERB
{
public:
	void bfmeReleaseERB(void);
	void bfmeAddRefERB(void) { ++m_bfmeRefERB; }

	unsigned char m_bfmeHeadERB[4];
	unsigned short m_bfmeRefERB;
};

class BfmeHostERB
{
public:
	void bfmeSetERB(BfmeTexERB **slot);

	unsigned char m_bfmeHeadERB[0x4c];
	struct BfmeSlotERB
	{
		BfmeTexERB *m_ptr;
		int m_mask;
	} m_bfmeSlotERB;
};

void BfmeHostERB::bfmeSetERB(BfmeTexERB **slot)
{
	BfmeTexERB *value = *slot;
	if (value == m_bfmeSlotERB.m_ptr)
		return;
	if (value != 0)
		value->bfmeAddRefERB();
	if (m_bfmeSlotERB.m_ptr != 0)
		m_bfmeSlotERB.m_ptr->bfmeReleaseERB();
	BfmeTexERB *fresh = *slot;
	BfmeSlotERB updated = { fresh, (fresh != 0) ? -1 : 0 };
	m_bfmeSlotERB = updated;
}
